class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is HostStatusKind) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    }    else if (value is BindPolicy) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    }    else if (value is ModelOptionsMsg) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is SessionConfigMsg) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is BenchConfigMsg) {
