/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<InferenceMessage> inferenceMessages( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel inferenceMessagesChannel =
      EventChannel('dev.flutter.pigeon.sherpa_inference.InferenceEventApi.inferenceMessages$instanceName', pigeonMethodCodec);
